        ki, ci = dice[i]
        for j in range(i+1, n):
            kj, cj = dice[j]
            if len(ci) > len(cj):
                small_c, large_c = cj, ci
            else:
                small_c, large_c = ci, cj
            s = 0
            for face, cnt in small_c.items():
                if face in large_c:
                    s += cnt * large_c[face]
            p = s / (ki * kj)
            if p > best:
                best = p
    print(f"{best:.15f}")

